inline const float* heavy_hex_3x3_noisy_eps015_ptm(int bond_id, float gamma) {
    int best = 0;
    float best_diff = fabsf(gamma - HEAVY_HEX_3x3_NOISY_EPS015_GAMMAS[0]);
    for (int i = 1; i < HEAVY_HEX_3x3_NOISY_EPS015_N_GAMMA; i++) {
        float diff = fabsf(gamma - HEAVY_HEX_3x3_NOISY_EPS015_GAMMAS[i]);
        if (diff < best_diff) { best = i; best_diff = diff; }
    }
    return HEAVY_HEX_3x3_NOISY_EPS015_GAMMA1_0[bond_id];
}
